mapper.update:
update `meattrade_withdraw` ww set ww.status = 'REJECTED', ww.auditor = #{operator}, ww.remark = #{remark},
ww.audit_time = #{datetime}
where ww.id = #{id} and ww.status = 'AUDITING'

mapper.select:
select ww.id, ww.short_id, ww.user_id, ww.supplier_id, ww.bank_card_json, ww.amount, ww.owner, ww.auditor,
ww.completer, ww.remark, ww.status, ww.audit_time, ww.cancel_time, ww.complete_time, ww.tenant, ww.deleted,
ww.create_by, ww.create_time, ww.update_by, ww.update_time
from `meattrade_withdraw` ww


        ww.create_time >= #{param.period.begin}


        and ww.create_time <= #{param.period.end}



            ww.supplier_id in

                #{supplierId}



            or (
            ww.id = #{id} or ww.short_id = #{id}
            )



        and ww.status = #{param.status.name}

    and ww.tenant = #{param.tenant}

order by ww.create_time desc
